      "path": "package.json",
      "content": "{\n  \"name\": \"@vfvrpq/dsh-search\",\n  \"version\": \"0.1.0\",\n  \"description\": \"DeepSeek first-party Search/Fetch API for DeepSeek Harness: three tools (deepseek_search / deepseek_fetch / deepseek_research) that return structured, reranked web results with search operators, page-to-Markdown fetching, and cost-aware defaults.\",\n  \"type\": \"module\",\n  \"license\": \"MIT\",\n  \"author\": \"439436269-ctrl\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/439436269-ctrl/dsh-search.git\"\n  },\n  \"homepage\": \"https://github.com/439436269-ctrl/dsh-search#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/439436269-ctrl/dsh-search/issues\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"registry\": \"https://registry.npmjs.org/\"\n  },\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"deepseek\",\n    \"search\",\n    \"fetch\",\n    \"web-search\",\n    \"rag\"\n  ],\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/**/*.js\",\n    \"lib/**/*.d.ts\",\n    \"CHANGELOG.md\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"engines\": {\n    \"node\": \">=22\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"^0.2.0-rc.2\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.2.0-rc.2\": \"compatible\"\n      }\n    }\n  },\n  \"scripts\": {\n    \"test\": \"node --test test/*.test.js\",\n    \"selftest\": \"node scripts/live-selftest.js\"\n  }\n}\n"
    },
    {
      "path": "lib/index.js",
      "content": "/**\n * dsh-search — DeepSeek first-party Search / Fetch tools for\n * DeepSeek Harness.\n *\n * This entry point only wires things together: it validates config, owns the\n * client lifecycle, contributes the guide section, and registers the tools\n * described in `./tools/`. Configuration lives in `./config.js`, key resolution\n * in `./keys.js`, the HTTP protocol in `./client.js`, the guide text in\n * `./prompt.js`.\n *\n * @module dsh-search\n */\n\nimport { defineTool } from \"@deepseek-ai/dsh-tools\";\n\nimport { SearchClient } from \"./client.js\";\nimport { Config, resolveConfig, validateConfig } from \"./config.js\";\nimport { guideText } from \"./prompt.js\";\nimport { createToolSpecs } from \"./tools.js\";\n\nexport const name = \"deepseek-search\";\n\nexport const inject = [\"tools\", \"systemPrompt\"];\n\nexport { Config, SearchClient };\n\nexport function apply(ctx, config) {\n\tconst settings = resolveConfig(config);\n\tvalidateConfig(settings);\n\n\t/** @type {SearchClient|undefined} */\n\tlet client;\n\tctx.effect(() => {\n\t\tclient = new SearchClient({\n\t\t\tbaseUrl: settings.baseUrl,\n\t\t\tapiKey: settings.apiKey,\n\t\t\ttimeoutMs: settings.timeoutMs,\n\t\t\tmaxRetries: settings.maxRetries,\n\t\t});\n\t\treturn () => {\n\t\t\tclient = undefined;\n\t\t};\n\t});\n\n\t/**\n\t * The live client, or a loud failure — reached only while the fiber is active.\n\t *\n\t * @returns {SearchClient} live client.\n\t */\n\tconst getClient = () => {\n\t\tif (!client) throw new Error(\"deepseek-search: client is not available\");\n\t\treturn client;\n\t};\n\n\tif (settings.promptEnabled) {\n\t\tctx.systemPrompt.section({\n\t\t\tname: \"deepseek-search:guide\",\n\t\t\torder: settings.promptOrder,\n\t\t\ttext: () => guideText(settings),\n\t\t});\n\t}\n\n\tfor (const spec of createToolSpecs({ client: getClient(), config: settings })) {\n\t\tctx.tools.register(\n\t\t\tdefineTool({\n\t\t\t\tname: spec.name,\n\t\t\t\tdescription: spec.description,\n\t\t\t\tparameters: spec.parameters,\n\t\t\t\toutput: {\n\t\t\t\t\tschema: spec.outputSchema,\n\t\t\t\t\trender: spec.render,\n\t\t\t\t\t...(spec.presentationMeta ? { presentationMeta: spec.presentationMeta } : {}),\n\t\t\t\t},\n\t\t\t\t...(spec.call ? { presentCall: spec.call } : {}),\n\t\t\t\texecute: spec.execute,\n\t\t\t}),\n\t\t);\n\t}\n}\n"
    },
    {
      "path": "lib/tools.js",
      "content": "/**\n * Tool registry: one tool per file, in the order the model should see them.\n *\n * @module dsh-search/tools\n */\n\nimport { clampInt, guarded, requireText } from \"./tools/shared.js\";\nimport { createSearchTool } from \"./tools/search.js\";\nimport { createFetchTool } from \"./tools/fetch.js\";\nimport { createResearchTool } from \"./tools/research.js\";\n\n/**\n * Build every tool spec for one plugin instance.\n *\n * @param {{client: import(\"./client.js\").SearchClient, config: Record<string, any>}} deps - plugin deps.\n * @returns {Array<Record<string, any>>} tool specs in presentation order.\n */\nexport function createToolSpecs({ client, config }) {\n\tconst ctx = { client, config, clampInt, guarded, requireText };\n\treturn [createSearchTool(ctx), createFetchTool(ctx), createResearchTool(ctx)];\n}\n"
